def build_exercises():
    """Retourne une liste de 520+ dictionnaires d'exercices uniques prêts pour SQLite."""
    entries = []
    seen_titles = set()

    def add_entry(title, subcat, primary, synergists, equip, diff, reps, tempo, bio_cue, steps, err_fix, prog):
        key = title.strip().lower()
        if key in seen_titles:
            return
        seen_titles.add(key)
        summary = f"{subcat} · {equip} · {diff} — Muscles : {primary}. Séries types : {reps}."
        body = (
            f"MUSCLES PRIMAIRES : {primary}\n"
            f"MUSCLES SYNERGISTES : {synergists}\n"
            f"MATÉRIEL : {equip} | NIVEAU : {diff} | VOLUME OPTIMAL : {reps} | TEMPO : {tempo}\n\n"
            f"REPÈRE BIOMÉCANIQUE :\n{bio_cue}\n\n"
            f"EXÉCUTION PAS-À-PAS :\n{steps}\n\n"
            f"ERREURS FRÉQUENTES & CORRECTIONS :\n{err_fix}\n\n"
            f"RÉGRESSION / PROGRESSION :\n{prog}"
        )
        meta = {
            "muscles_primaires": [m.strip() for m in primary.split(",")],
            "muscles_synergistes": [m.strip() for m in synergists.split(",")],
            "materiel": equip,
            "difficulte": diff,
            "reps_optimales": reps,
            "tempo": tempo,
            "erreurs": err_fix,
            "progressions": prog,
        }
        tags = f"exercice,{subcat.lower()},{primary.lower()},{equip.lower()},{diff.lower()}"
        entries.append({
            "category": "exercice",
            "subcategory": subcat,
            "title": title,
            "summary": summary,
            "body": body,
            "tags": tags,
            "metadata_json": json.dumps(meta, ensure_ascii=False),
        })

    # 1. Core exercises (ultra-detailed)
    for row in CORE_EXERCISES:
        add_entry(*row)

    # 2. Matrix variants
    for base_name, fam, prim, syn, variants in EXERCISE_CATALOG_MATRIX:
        for suffix, equip, diff, reps, focus, err in variants:
            full_title = suffix if (base_name.lower() in suffix.lower() or fam in ("Ischio-jambiers", "Kettlebell", "Cardio / Plyo", "Bras (Biceps & Triceps)", "Gainage & Abdos", "Épaules", "Tirages Dos")) else f"{base_name} {suffix}"
            if base_name in ("Squat", "Fentes", "Soulevé de terre") and not suffix.lower().startswith(base_name.lower()):
                full_title = f"{base_name} {suffix}"
            elif base_name == "Développé Pectoraux" and not any(suffix.startswith(p) for p in ("Écartés", "Pompes", "Dips", "Landmine", "Spoto", "Larsen", "Squeeze", "Svend")):
                full_title = f"Développé {suffix}"
            else:
                full_title = suffix if (base_name not in ("Squat", "Fentes", "Soulevé de terre")) else full_title

            steps = (
                f"1. Mise en place ({equip}) : stabilisez vos appuis, verrouillez un rachis neutre et engagez la ceinture scapulaire/abdominale. "
                f"2. Phase excentrique contrôlée : recherchez un étirement actif sur {prim} dans votre amplitude articulaire saine. "
                f"3. Phase concentrique fluide : poussez/tirez de façon intentionnelle sans compensation ni élan excessif."
            )
            prog = f"Adaptez d'abord le tempo et l'amplitude à charge modérée (RIR 2-3), puis progressez par +2,5 à 5% de charge ou +1-2 répétitions sur {reps}."
            add_entry(full_title, fam, prim, syn, equip, diff, reps, "3-1-1-0", focus, steps, err, prog)

    # 3. Specialized + Extra distinct + Modality + Sports/Machines
    for block in (SPECIALIZED_EXERCISES, EXTRA_DISTINCT_EXERCISES, EXTRA_SPORTS_AND_MACHINES):
        for title, subcat, prim, syn, equip, diff, reps, cue, err in block:
            steps = (
                f"1. Installation ({equip}) : alignez l'articulation cible et stabilisez le tronc. "
                f"2. Mouvement contrôlé : ciblez prioritairement {prim} avec l'assistance de {syn}. "
                f"3. Fin de mouvement : contrôlez la transition excentrique-concentrique sans à-coup."
            )
            prog = f"Maîtrisez {reps} en RIR 2 avant d'augmenter la charge, le temps sous tension ou la complexité unilatérale."
            add_entry(title, subcat, prim, syn, equip, diff, reps, "2-1-1-0", cue, steps, err, prog)

    for title, subcat, prim, syn, equip, diff, reps, tempo, cue, err in ADDITIONAL_VARIATIONS:
        steps = (
            f"1. Position initiale ({equip}) : créez une base stable et verrouillez la posture neutre. "
            f"2. Exécution au tempo {tempo} : maintenez une tension mécanique continue sur {prim}. "
            f"3. Récupération contrôlée entre les séries ({reps}) pour préserver la qualité gestuelle."
        )
        prog = f"Progression recommandée : double progression (atteignez le haut de la fourchette {reps} proprement avant de monter la charge)."
        add_entry(title, subcat, prim, syn, equip, diff, reps, tempo, cue, steps, err, prog)

    for title, subcat, prim, syn, equip, diff, reps, tempo, cue, err in MODALITY_PACKS:
        steps = (
            f"1. Préparation ({equip}) : ajustez l'ergonomie pour cibler {prim} sans gêne articulaire. "
            f"2. Réalisation au tempo {tempo} : contrôlez l'étirement et la contraction en respirant activement. "
            f"3. Volume cible : {reps} à 1-2 répétitions de réserve (RIR 1-2)."
        )
        prog = "Progressez d'abord en qualité d'amplitude et contrôle du tempo, puis ajoutez charge ou volume."
        add_entry(title, subcat, prim, syn, equip, diff, reps, tempo, cue, steps, err, prog)

    return entries


if __name__ == "__main__":
    ex = build_exercises()
    print(f"Total exercises generated: {len(ex)}")
